function escapeHtml(value = "") {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function formatDate(value) {
  if (!value) return new Date().toLocaleDateString("en-GB").replaceAll("/", "-");
  if (value instanceof Date) return value.toLocaleDateString("en-GB").replaceAll("/", "-");
  return String(value);
}

function replaceKnown(text, values) {
  let out = text;

  // Digital Marketing merge fields
  out = out.replace(/21-02-2026/g, values.agreement_date ?? "{{agreement_date}}");
  out = out.replace(/INDIRAGANDHI NURSERY AND PRIMARY SCHOOL/g, values.client_name ?? "{{client_name}}");
  out = out.replace(/School No:396, E 4th St, Pudukkottai, Tamil Nadu 622001/g, values.client_address ?? "{{client_address}}");
  out = out.replace(/₹23,000/g, values.digital_yearly_fee ?? "{{digital_yearly_fee}}");
  out = out.replace(/₹7,000/g, values.digital_discount ?? "{{digital_discount}}");
  out = out.replace(/₹16,000/g, values.digital_amount ?? "{{digital_amount}}");
  out = out.replace(/GST: 18%/g, "GST: " + (values.digital_gst ?? "{{digital_gst}}"));
  out = out.replace(/₹2,000/g, values.commission_without_erp ?? "{{commission_without_erp}}");
  out = out.replace(/₹1,000/g, values.commission_with_erp ?? "{{commission_with_erp}}");

  // ERP merge fields
  out = out.replace(/VENUS VIDYALAYA MATRICULATION SCHOOL/g, values.client_name ?? "{{client_name}}");
  out = out.replace(/Veppilaipatty \(po\), Valapady \(tk\), Salem \(Dt\) Pin code : 636202/g, values.client_address ?? "{{client_address}}");

  return out;
}

function renderLine(line, values) {
  const classes = ["exact-text-line"];
  if (line.bold) classes.push("exact-bold");
  if (line.italic) classes.push("exact-italic");
  const text = escapeHtml(replaceKnown(line.t, values));
  return `<span
    class="${classes.join(" ")}"
    contenteditable="true"
    suppresscontenteditablewarning="true"
    style="left:${line.x}px;top:${line.y}px;width:${Math.max(line.w + 8, 10)}px;min-height:${Math.max(line.h + 2, 10)}px;font-family:${escapeHtml(line.font)};font-size:${line.size}px;line-height:${line.h}px;"
  >${text}</span>`;
}

function renderPage(lines, values, key) {
  const text = lines.map(line => renderLine(line, values)).join("");
  return `
    <section class="exact-agreement-page" data-page="${key}">
      <img class="exact-brand-logo" src="${ASSETS.logo}" alt="" />
      <img class="exact-top-ribbon" src="${ASSETS.topRibbon}" alt="" />
      <img class="exact-bottom-ribbon" src="${ASSETS.bottomRibbon}" alt="" />
      ${text}
    </section>`;
}

function valuesFor(lead = {}, agreementData = {}, amounts = {}) {
  return {
    agreement_date: escapeHtml(formatDate(agreementData.date || agreementData.agreementDate || new Date())),
    client_name: escapeHtml(lead.name || lead.school || lead.schoolName || agreementData.clientName || ""),
    client_address: escapeHtml(lead.schoolAddress || lead.address || agreementData.clientAddress || ""),
    digital_yearly_fee: escapeHtml(amounts.digitalYearlyFee || "₹23,000"),
    digital_discount: escapeHtml(amounts.digitalDiscount || "₹7,000"),
    digital_amount: escapeHtml(amounts.digitalMarketing || amounts.digitalAmount || "₹16,000"),
    digital_gst: escapeHtml(amounts.digitalGst || "18%"),
    commission_without_erp: escapeHtml(amounts.commissionWithoutErp || "₹2,000"),
    commission_with_erp: escapeHtml(amounts.commissionWithErp || "₹1,000"),
    erp_plan_label: escapeHtml(amounts.erpPlanLabel || ""),
    erp_amount: escapeHtml(amounts.erpAmount || ""),
    erp_gst: escapeHtml(amounts.erpGst || "18%"),
    erp_total_amount: escapeHtml(amounts.erpTotalAmount || amounts.erpAmount || ""),
  };
}

export function buildDigitalMarketingAgreementHtml(selectedServices = {}, amounts = {}, lead = {}, agreementData = {}) {
  const values = valuesFor(lead, agreementData, amounts);
  return EXACT_AGREEMENT_STYLES + `<div class="exact-agreement-document exact-digital-agreement">${DM_PAGES.map((p, i) => renderPage(p, values, `digital-${i+1}`)).join("")}</div>`;
}

export function buildErpAgreementHtml(selectedServices = {}, amounts = {}, lead = {}, agreementData = {}) {
  const values = valuesFor(lead, agreementData, amounts);
  return EXACT_AGREEMENT_STYLES + `<div class="exact-agreement-document exact-erp-agreement">${ERP_PAGES.map((p, i) => renderPage(p, values, `erp-${i+1}`)).join("")}</div>`;
}

export function buildAdmissionDashboardAgreementHtml(selectedServices = {}, amounts = {}, lead = {}, agreementData = {}) {
  return buildDigitalMarketingAgreementHtml(selectedServices, { ...amounts, digitalMarketing: amounts.digitalMarketing || "NO COST" }, lead, agreementData);
}

export function buildAgreementHtml(selectedServices = {}, amounts = {}, lead = {}, agreementData = {}) {
  const docs = [];
  if (selectedServices.erp) docs.push(buildErpAgreementHtml(selectedServices, amounts, lead, agreementData));
  if (selectedServices.digitalMarketing || selectedServices.admissionDashboard) {
    docs.push(buildDigitalMarketingAgreementHtml(selectedServices, amounts, lead, agreementData));
  }
  if (!docs.length) throw new Error("Please select at least one agreement service.");
  return docs.join('<div style="page-break-before:always;break-before:page;height:0"></div>');
}

export const AGREEMENT_TEMPLATES = {
  erp: { key: "erp", label: "ERP Software Agreement", build: buildErpAgreementHtml },
  digitalMarketing: { key: "digitalMarketing", label: "Digital Marketing & Admin Dashboard Agreement", build: buildDigitalMarketingAgreementHtml },
  admissionDashboard: { key: "admissionDashboard", label: "Admission Dashboard Agreement", build: buildAdmissionDashboardAgreementHtml },
};

export default {
  EXACT_AGREEMENT_STYLES,
  AGREEMENT_TEMPLATES,
  buildAgreementHtml,
  buildErpAgreementHtml,
  buildDigitalMarketingAgreementHtml,
  buildAdmissionDashboardAgreementHtml,
};
